    a_intervals = sorted([x for x in a if x[0] < x[1]])
    b_intervals = sorted([x for x in b if x[0] < x[1]])

    # Merge overlapping intervals in both lists
    def merge_intervals(intervals):
        if not intervals:
            return []
        merged = [intervals[0]]
        for current in intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                merged[-1] = [last[0], max(last[1], current[1])]
            else:
                merged.append(current)
        return merged

    a_merged = merge_intervals(a_intervals)
    b_merged = merge_intervals(b_intervals)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the parts that don't overlap
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    if not result:
        return []

    result = sorted(result)
    merged_result = [result[0]]
